import { useEffect } from 'react'

export default function Integrations() {
	useEffect(() => {
		const section = document.getElementById('intergration')
		if (!section) return

		// ── Scroll-reveal: heading & subhead fade up ──────────────────────────────
		const heading = section.querySelector('[data-framer-name="Heading"]')
		const subhead = section.querySelector('[data-framer-name="SubHead"]')

		const revealEls = [heading, subhead].filter(Boolean)

		revealEls.forEach((el, idx) => {
			el.style.opacity = '0'
			el.style.transform = 'translateY(48px)'
			el.style.transition = `opacity 0.9s cubic-bezier(0.16, 1, 0.3, 1) ${idx * 0.14}s, transform 0.9s cubic-bezier(0.16, 1, 0.3, 1) ${idx * 0.14}s`
			el.style.willChange = 'opacity, transform'
		})

		const revealObserver = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting) {
						revealEls.forEach((el) => {
							el.style.opacity = '1'
							el.style.transform = 'translateY(0px)'
						})
						revealObserver.disconnect()
					}
				})
			},
			{ threshold: 0.12 },
		)

		revealObserver.observe(section)

		// ── Semicircular Arc Layout Coordinates for the 11 Company Logos ────────
		const arcLayout = [
			{ dx: -420, dy: 60, rot: -24, scale: 0.68 }, // 00: TCS
			{ dx: -375, dy: 2,  rot: -19, scale: 0.69 }, // 01: Infosys
			{ dx: -305, dy: -52, rot: -14, scale: 0.70 }, // 02: Wipro
			{ dx: -215, dy: -96, rot: -9, scale: 0.71 }, // 03: Accenture
			{ dx: -110, dy: -124, rot: -4, scale: 0.73 }, // 04: Cognizant
			{ dx: 0,    dy: -134, rot: 0,  scale: 0.80 }, // 05: Google (Crown Apex)
			{ dx: 110,  dy: -124, rot: 4,  scale: 0.73 }, // 06: Microsoft
			{ dx: 215,  dy: -96, rot: 9,   scale: 0.71 }, // 07: Amazon
			{ dx: 305,  dy: -52,  rot: 14, scale: 0.70 }, // 08: Deloitte
			{ dx: 375,  dy: 2,   rot: 19,  scale: 0.69 }, // 09: IBM
			{ dx: 420,  dy: 60,   rot: 24, scale: 0.68 }, // 10: Capgemini
		]

		const logoContainerClasses = [
			'framer-nak539-container',
			'framer-xj4vat-container',
			'framer-14a8m8s-container',
			'framer-ekfrev-container',
			'framer-17nazwv-container',
			'framer-16ucjje-container',
			'framer-ofe7pf-container',
			'framer-ymoy0n-container',
			'framer-n2g6jl-container',
			'framer-17i2jiy-container',
			'framer-1fryaok-container',
		]

		const desktopWrap = section.querySelector('.framer-dwu6et-container')
		const logoFan = desktopWrap ? desktopWrap.querySelector('.framer-eq5cf') : null
		const logoEls = desktopWrap
			? logoContainerClasses.map((c) => desktopWrap.querySelector('.' + c)).filter(Boolean)
			: []

		// Set initial logo state centered and scaled down
		logoEls.forEach((el, idx) => {
			const pos = arcLayout[idx] || { dx: 0, dy: 0, rot: 0, scale: 0.7 }
			el.style.opacity = '0'
			el.style.transform = `translate(${pos.dx * 0.3}px, ${pos.dy * 0.3}px) rotate(${pos.rot * 0.3}deg) scale(0.3)`
			el.style.willChange = 'opacity, transform'
			el.style.transformOrigin = 'center center'

			// Add hover interaction
			const card = el.querySelector('.framer-skyyt1')
			if (card) {
				card.style.transition = 'transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s ease'
				card.style.cursor = 'pointer'
				el.addEventListener('mouseenter', () => {
					el.style.zIndex = '50'
					el.style.transform = `translate(${pos.dx}px, ${pos.dy - 12}px) rotate(${pos.rot * 0.5}deg) scale(${pos.scale * 1.15})`
					card.style.boxShadow = '0 20px 35px -8px rgba(0, 102, 255, 0.28), 0 10px 15px -4px rgba(0, 0, 0, 0.1)'
				})
				el.addEventListener('mouseleave', () => {
					el.style.zIndex = ''
					el.style.transform = `translate(${pos.dx}px, ${pos.dy}px) rotate(${pos.rot}deg) scale(${pos.scale})`
					card.style.boxShadow = '0px 5px 15px 0px rgba(0, 0, 0, 0.1)'
				})
			}
		})

		let logoRevealed = false
		const logoObserver = new IntersectionObserver(
			(entries) => {
				entries.forEach((entry) => {
					if (entry.isIntersecting && !logoRevealed) {
						logoRevealed = true
						logoEls.forEach((el, idx) => {
							const pos = arcLayout[idx] || { dx: 0, dy: 0, rot: 0, scale: 0.7 }
							setTimeout(() => {
								el.style.opacity = '1'
								el.style.transform = `translate(${pos.dx}px, ${pos.dy}px) rotate(${pos.rot}deg) scale(${pos.scale})`
								el.style.transition =
									'opacity 0.75s cubic-bezier(0.16, 1, 0.3, 1), transform 0.85s cubic-bezier(0.34, 1.4, 0.64, 1)'
							}, idx * 45)
						})
						logoObserver.disconnect()
					}
				})
			},
			{ threshold: 0.1 },
		)

		if (desktopWrap) logoObserver.observe(desktopWrap)

		// ── Scroll-linked parallax on the arch fan ────────────────────────────────
		let rafPending = false
		const handleScroll = () => {
			if (rafPending) return
			rafPending = true
			requestAnimationFrame(() => {
				const rect = section.getBoundingClientRect()
				const winH = window.innerHeight
				if (rect.top < winH && rect.bottom > 0 && logoFan) {
					const progress = (winH - rect.top) / (winH + rect.height) - 0.5
					const driftY = progress * 24
					logoFan.style.transform = `translateY(${driftY}px)`
					logoFan.style.transition = 'transform 0.12s linear'
				}
				rafPending = false
			})
		}

		window.addEventListener('scroll', handleScroll, { passive: true })

		return () => {
			revealObserver.disconnect()
			logoObserver.disconnect()
			window.removeEventListener('scroll', handleScroll)
		}
	}, [])

	return (
		<section
			className="framer-wmucdu"
			data-framer-name="Integrations"
			id="intergration"
			dangerouslySetInnerHTML={{ __html: content }}
		/>
	)
}
